    public static class Serializer implements IAttachmentSerializer<CompoundTag, WerewolfPlayer> {

        @Override
        public @NotNull WerewolfPlayer read(@NotNull IAttachmentHolder holder, @NotNull CompoundTag tag, HolderLookup.Provider provider) {
            if(holder instanceof Player player) {
                var werewolf = new WerewolfPlayer(player);
                werewolf.deserializeNBT(provider, tag);
                return werewolf;
            }
            throw new IllegalArgumentException("Expected Player, got " + holder.getClass().getSimpleName());
        }

        @Override
        public CompoundTag write( WerewolfPlayer attachment, HolderLookup.Provider provider) {
            return attachment.serializeNBT(provider);
        }
    }

    public static class Factory implements Function<IAttachmentHolder, WerewolfPlayer> {

        @Override
        public WerewolfPlayer apply(IAttachmentHolder holder) {
            if (holder instanceof Player player) {
                return new WerewolfPlayer(player);
            }
            throw new IllegalArgumentException("Cannot create hunter player attachment for holder " + holder.getClass() + ". Expected Player");
        }
    }
}

package de.teamlapen.werewolves.entities.player.werewolf;

import de.teamlapen.lib.lib.storage.ISyncableSaveData;
import net.minecraft.core.HolderLookup;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.util.Mth;
import org.jetbrains.annotations.NotNull;

import javax.annotation.Nonnull;

public class LevelHandler implements ISyncableSaveData {
    private static final String KEY_LEVEL = "level";
    private final WerewolfPlayer player;
    private int levelProgress;

    public LevelHandler(WerewolfPlayer player) {
        this.player = player;
    }

    public boolean canLevelUp() {
        return this.player.getLevel() != this.player.getMaxLevel() && this.levelProgress >= getNeededProgress();
    }

    public float getLevelPerc() {
        return Mth.clamp((float) this.levelProgress / getNeededProgress(), 0, 1);
    }

    public int getLevelProgress() {
        return this.levelProgress;
    }

    public int getNeededProgress() {
        return WerewolfLevelConf.getInstance().getRequirementOpt(this.player.getLevel() + 1).map(x -> x.xpAmount).orElse(Integer.MAX_VALUE);
    }

    public void increaseProgress(int amount) {
        this.levelProgress += amount;
    }

    public void reset() {
        this.levelProgress = 0;
    }

    @Override
    public @NotNull CompoundTag serializeNBT(HolderLookup.@NotNull Provider provider) {
        CompoundTag nbt = new CompoundTag();
        nbt.putInt("progress", levelProgress);
        return nbt;
    }

    @Override
    public void deserializeNBT(HolderLookup.@NotNull Provider provider, @NotNull CompoundTag compoundTag) {
        if (compoundTag.contains("progress")) {
            levelProgress = compoundTag.getInt("progress");
        }
    }

    @Override
    public void deserializeUpdateNBT(HolderLookup.@NotNull Provider provider, @NotNull CompoundTag compoundTag) {
        deserializeNBT(provider, compoundTag);
    }

    @Override
    public @NotNull CompoundTag serializeUpdateNBT(HolderLookup.@NotNull Provider provider) {
        return serializeNBT(provider);
    }

    @Override
    public String nbtKey() {
        return KEY_LEVEL;
    }
}

@Override
public @NotNull CompoundTag serializeNBT(HolderLookup.Provider provider) {
    CompoundTag nbt = new CompoundTag();
    nbt.putString("lastForm", this.form.getName());
    CompoundTag tag = new CompoundTag();
    nbt.put("inventory", tag);
    this.inventories.forEach((form, armor) -> {
        ListTag list = new ListTag();
        for (int i = 0; i < armor.size(); i++) {
            ItemStack stack = armor.get(i);
            if (!stack.isEmpty()) {
                CompoundTag itemTag = new CompoundTag();
                itemTag.putByte("Slot", (byte) i);
                list.add(stack.save(provider, itemTag));
            }
        }
        tag.put(form.getName(), list);
    });
    return nbt;
}

@Override
public void deserializeNBT(HolderLookup.Provider provider, @NotNull CompoundTag compoundTag) {
    this.form = Objects.requireNonNullElse(WerewolfForm.getForm(compoundTag.getString("lastForm")), WerewolfForm.NONE);
    CompoundTag inventory = compoundTag.getCompound("inventory");
    inventory.getAllKeys().stream().map(WerewolfForm::getForm).forEach(form -> {
        ListTag list = inventory.getList(form.getName(), 10);
        for (int i = 0; i < list.size(); i++) {
            CompoundTag itemTag = list.getCompound(i);
            int slot = itemTag.getByte("Slot") & 255;
            ItemStack stack = ItemStack.parseOptional(provider, itemTag);
            this.inventories.get(form).set(slot, stack);
        }
    });
}

@Override
public void deserializeUpdateNBT(HolderLookup.Provider provider, @NotNull CompoundTag compoundTag) {
    deserializeNBT(provider, compoundTag);
}

package de.teamlapen.werewolves.core;

import de.teamlapen.werewolves.api.WerewolvesAttachments;
import de.teamlapen.werewolves.entities.player.werewolf.WerewolfPlayer;
import de.teamlapen.werewolves.util.REFERENCE;
import de.teamlapen.werewolves.world.LevelDamage;
import de.teamlapen.werewolves.world.LevelWolfsbane;
import net.neoforged.bus.api.IEventBus;
import net.neoforged.neoforge.attachment.AttachmentType;
import net.neoforged.neoforge.registries.DeferredHolder;
import net.neoforged.neoforge.registries.DeferredRegister;
import net.neoforged.neoforge.registries.NeoForgeRegistries;

public class ModAttachments {
    public static final DeferredRegister<AttachmentType<?>> ATTACHMENT_TYPES = DeferredRegister.create(NeoForgeRegistries.Keys.ATTACHMENT_TYPES, REFERENCE.MODID);

    public static final DeferredHolder<AttachmentType<?>, AttachmentType<LevelWolfsbane>> LEVEL_WOLFSBANE = ATTACHMENT_TYPES.register(WerewolvesAttachments.Keys.WOLFSBANE_HANDLER.getPath(), () -> AttachmentType.builder(LevelWolfsbane::new).build());
    public static final DeferredHolder<AttachmentType<?>, AttachmentType<LevelDamage>> LEVEL_DAMAGE = ATTACHMENT_TYPES.register(WerewolvesAttachments.Keys.DAMAGE_HANDLER.getPath(), () -> AttachmentType.builder(new LevelDamage.Factory()).build());

    public static final DeferredHolder<AttachmentType<?>, AttachmentType<WerewolfPlayer>> WEREWOLF_PLAYER = ATTACHMENT_TYPES.register(WerewolvesAttachments.Keys.WEREWOLF_PLAYER.getPath(), () -> AttachmentType.builder(new WerewolfPlayer.Factory()).serialize(new WerewolfPlayer.Serializer()).copyOnDeath().build());

    static void register(IEventBus bus) {
        ATTACHMENT_TYPES.register(bus);
    }

}
